import{_ as t,o as a,c as i,a2 as e}from"./chunks/framework.BWuWLRhz.js";const k=JSON.parse('{"title":"开发规则源","description":"","frontmatter":{},"headers":[],"relativePath":"guide/rule-source.md","filePath":"guide/rule-source.md","lastUpdated":1785861127000}'),n={name:"guide/rule-source.md"};function o(l,s,d,r,h,p){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="开发规则源" tabindex="-1">开发规则源 <a class="header-anchor" href="#开发规则源" aria-label="Permalink to &quot;开发规则源&quot;">​</a></h1><p>规则源让任何人都能维护并分发自己的清理规则。它就是一个托管在 HTTP 上的 JSON 文件，用户在 CZeroX 里填入链接即可订阅，之后<strong>每天自动更新一次</strong>。</p><div class="tip custom-block"><p class="custom-block-title">面向谁</p><p>这篇文档写给想向 CZero 用户发布规则的开发者。<strong>推荐自建仓库</strong>维护规则源，CZero 仓库也留了一个备用的存放位置。</p><p>只是想加几条自己用的路径，请直接在 CZeroX 的「自定义规则配置 → 模块内置规则」里添加，不用做规则源。</p></div><h2 id="文件格式" tabindex="-1">文件格式 <a class="header-anchor" href="#文件格式" aria-label="Permalink to &quot;文件格式&quot;">​</a></h2><p>规则源和模块本地的 <code>clean_paths.json</code> 是同构的，只在顶层多了署名信息：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;老王的规则源&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;author&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@laowang&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026.08.04&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;homepage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/laowang/czero-rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;groups&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;微博&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;paths&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;/storage/emulated/0/Android/data/com.sina.weibo/cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;/data/data/com.sina.weibo/files/weibo_log&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;小红书&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;paths&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;/storage/emulated/0/Android/data/com.xingin.xhs/cache/*&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>把自己在 CZeroX 里整理好的规则导出，补上 <code>name</code> 和 <code>author</code>，就是一个可用的规则源。</p><h2 id="顶层字段" tabindex="-1">顶层字段 <a class="header-anchor" href="#顶层字段" aria-label="Permalink to &quot;顶层字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td><strong>是</strong></td><td>源名称，显示在用户的规则源卡片标题上。超过 64 字符会被截断</td></tr><tr><td><code>author</code></td><td>string</td><td>否</td><td>作者署名，显示在标题下方。上限 64 字符</td></tr><tr><td><code>version</code></td><td>string</td><td>否</td><td>版本标识，随便用什么格式，日期最直观。上限 32 字符</td></tr><tr><td><code>homepage</code></td><td>string</td><td>否</td><td>项目主页。上限 256 字符</td></tr><tr><td><code>groups</code></td><td>array</td><td><strong>是</strong></td><td>规则分组，至少要有一条有效路径</td></tr></tbody></table><p>缺少 <code>name</code>，或者 <code>groups</code> 里挑不出任何合法路径，添加时都会被拒绝。</p><h2 id="groups-字段" tabindex="-1">groups 字段 <a class="header-anchor" href="#groups-字段" aria-label="Permalink to &quot;groups 字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>否</td><td>分组名。留空则显示为「未分组」</td></tr><tr><td><code>enabled</code></td><td>bool</td><td>否</td><td><strong>缺省为 <code>true</code></strong>。写 <code>false</code> 表示这一组默认不生效，用户可以在应用里打开</td></tr><tr><td><code>paths</code></td><td>array</td><td><strong>是</strong></td><td>该组的清理路径</td></tr></tbody></table><p>分组只是给人看的组织方式，清理时会被摊平。但请认真分组——用户是按分组来启停和浏览规则的，一个源里把几百条路径全塞进一个组会很难用。</p><h2 id="路径写法" tabindex="-1">路径写法 <a class="header-anchor" href="#路径写法" aria-label="Permalink to &quot;路径写法&quot;">​</a></h2><p>路径<strong>必须是绝对路径</strong>，支持 glob 通配：</p><table tabindex="0"><thead><tr><th>写法</th><th>含义</th></tr></thead><tbody><tr><td><code>*</code></td><td>匹配单层里的任意字符</td></tr><tr><td><code>?</code></td><td>匹配单个字符</td></tr><tr><td><code>[abc]</code></td><td>匹配字符集里的一个</td></tr><tr><td><code>**</code></td><td>递归匹配任意层级目录</td></tr></tbody></table><p>几个常见的起点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/storage/emulated/0/Android/data/&lt;包名&gt;/     应用外部私有目录</span></span>
<span class="line"><span>/data/data/&lt;包名&gt;/                           应用内部数据目录</span></span>
<span class="line"><span>/data/user/0/&lt;包名&gt;/                         同上，多用户路径写法</span></span>
<span class="line"><span>/data/media/0/                               等价于 /storage/emulated/0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">目录会被递归清理</p><p>写一个目录路径，意味着<strong>该目录下所有文件</strong>都会被清掉，然后连空目录一起删除。务必精确到 <code>cache</code>、<code>log</code> 这类真正的缓存目录，不要写 <code>files</code> 这种可能装着用户数据的父目录。</p></div><h2 id="会被拒绝的路径" tabindex="-1">会被拒绝的路径 <a class="header-anchor" href="#会被拒绝的路径" aria-label="Permalink to &quot;会被拒绝的路径&quot;">​</a></h2><p>拉取时逐条校验，不合规的<strong>单条丢弃</strong>，不会让整个源失败：</p><ul><li>不是以 <code>/</code> 开头的相对路径</li><li>路径里含有 <code>..</code>（防止回溯到目标之外）</li><li>长度超过 512 字符，或短于 2 个字符</li></ul><h2 id="体量限制" tabindex="-1">体量限制 <a class="header-anchor" href="#体量限制" aria-label="Permalink to &quot;体量限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>数值</th><th>超出后</th></tr></thead><tbody><tr><td>文件大小</td><td>2 MB</td><td>整个源被拒绝</td></tr><tr><td>路径条数</td><td>5000 条</td><td>超出部分被丢弃，前 5000 条正常生效</td></tr></tbody></table><h2 id="托管" tabindex="-1">托管 <a class="header-anchor" href="#托管" aria-label="Permalink to &quot;托管&quot;">​</a></h2><h3 id="推荐-自建仓库" tabindex="-1">推荐：自建仓库 <a class="header-anchor" href="#推荐-自建仓库" aria-label="Permalink to &quot;推荐：自建仓库&quot;">​</a></h3><p>任何能返回 JSON 的 HTTPS 地址都可以。最省事的做法是开一个自己的 GitHub 仓库：</p><ol><li>新建一个公开仓库，比如 <code>你的用户名/czero-rules</code></li><li>把规则文件放进去，例如 <code>rules.json</code></li><li>用 raw 链接分发：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/&lt;用户名&gt;/&lt;仓库&gt;/main/rules.json</span></span></code></pre></div><p>响应必须是裸的 JSON 文本。注意 GitHub 的<strong>网页地址</strong>（<code>github.com/.../blob/...</code>）返回的是 HTML 页面，不是 JSON，用户填了会报「文件不是合法的 JSON」。</p><div class="warning custom-block"><p class="custom-block-title">只收 http/https</p><p><code>file://</code>、<code>content://</code> 之类的协议一律拒绝。</p></div><p>自建的好处是你完全掌握自己的规则：什么时候更新、更新什么都不用等别人；用 Git 管理规则，改错了能回滚，用户提 issue 你能对着 diff 看。发布时记得同步更新 JSON 里的 <code>version</code>，用户在应用里能看到版本变化。</p><div class="tip custom-block"><p class="custom-block-title">不用担心访问次数</p><p><code>raw.githubusercontent.com</code> 的限流是<strong>按访问者 IP</strong> 算的，不是按仓库算的，所以你的仓库被多少人订阅都不受影响。而且每个用户每个源一天只拉一次。</p></div><h3 id="备用-放到-czero-仓库" tabindex="-1">备用：放到 CZero 仓库 <a class="header-anchor" href="#备用-放到-czero-仓库" aria-label="Permalink to &quot;备用：放到 CZero 仓库&quot;">​</a></h3><p>实在不方便自己维护仓库，可以开一个 <a href="https://github.com/Xocio/CZero/issues" target="_blank" rel="noreferrer">issue</a> 申请把 JSON 放到 CZero 仓库的 <code>rules/public/</code> 目录，地址是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/Xocio/CZero/main/rules/public/&lt;文件名&gt;.json</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">仅代为存放</p><p>CZero <strong>不审核</strong>规则内容，放在这里不代表经过检查或获得背书，规则的正确性与安全性仍由作者本人负责。这只是给没有条件自建仓库的人留的路，能自建就自建。</p></div><h2 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to &quot;订阅&quot;">​</a></h2><p>CZeroX → 设置 → 自定义规则配置 → 右上角 <code>⋯</code> → 添加规则源 → 粘贴链接。</p><p>添加成功后会多出一张卡片，标题是源里的 <code>name</code>，副标题是 <code>author</code>，卡片上能看到分组数、规则数和上次更新时间。点卡片进去可以逐条查看。</p><h2 id="更新机制" tabindex="-1">更新机制 <a class="header-anchor" href="#更新机制" aria-label="Permalink to &quot;更新机制&quot;">​</a></h2><ul><li>用户打开规则源页面时，若距上次同步超过 <strong>24 小时</strong>，会自动拉取所有已启用的源</li><li>也可以在卡片上点刷新图标手动更新</li><li>更新时该源名下的规则<strong>整体替换</strong>：以你的源文件为准</li><li>重复添加同一个 URL 视为更新，不会产生两张卡片</li></ul><div class="warning custom-block"><p class="custom-block-title">用户的本地改动会被覆盖</p><p>用户可以在本地增删改你的源规则（比如临时停用某一组），但这些改动会在下次更新时被源文件冲掉——归属由 JSON 里的 <code>source</code> 键决定，更新只认源文件。这是设计如此，用户想长期保留的改动应该放到内置规则里。</p></div><h2 id="执行" tabindex="-1">执行 <a class="header-anchor" href="#执行" aria-label="Permalink to &quot;执行&quot;">​</a></h2><p>你的规则会和内置规则一起交给 <code>list/customize</code> 处理，行为完全一致：</p><ul><li><strong>回收站</strong>：匹配到的文件是被移入 <code>/storage/emulated/0/Recycle</code>，不是直接删除，用户可以恢复，默认保留 7 天</li><li><strong>时序屏障</strong>：若用户开启，只有修改时间早于 N 天的文件才会被清理</li><li><strong>白名单</strong>：用户的 <code>clean_whitelist.json</code> 优先级更高，命中白名单的路径会被跳过</li><li><strong>嵌套去重</strong>：父目录已在清理列表里时，它下面的子路径会被自动忽略</li></ul><p>所以不必担心写重复，但要担心写宽——写错一条能删掉用户的数据。</p><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><ol><li><strong>先在自己设备上验证</strong>。把规则填进 CZeroX 的内置规则跑一轮，确认清理量和应用行为都正常，再发布。</li><li><strong>只清可再生的数据</strong>。缓存、日志、崩溃转储、临时下载是安全的；聊天记录、草稿、下载目录、账号凭据不要碰。</li><li><strong>分组按应用切</strong>。一个应用一组，组名用应用中文名，用户才好按需启停。</li><li><strong>改动时更新 <code>version</code></strong>。用户看不到 diff，但能看到版本号变化。</li><li><strong>谨慎使用 <code>**</code></strong>。递归匹配在大目录上既慢又容易误伤。</li><li><strong>默认停用有风险的组</strong>。拿不准的规则写 <code>&quot;enabled&quot;: false</code>，让用户自己决定要不要开。</li></ol>`,49)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
